export function buildTourneyMatches(size: 4 | 8): TMatch[] {
  const qf: Tri = ["Quarter-Final", "کوارٹر فائنل", "ربع النهائي"];
  const sf: Tri = ["Semi-Final", "سیمی فائنل", "نصف النهائي"];
  const fin: Tri = ["Final", "فائنل", "النهائي"];
  const m = (
    id: number,
    round: number,
    label: Tri,
    blue: number | null,
    red: number | null,
    blueFrom: number | null,
    redFrom: number | null
  ): TMatch => ({ id, round, label, blue, red, blueFrom, redFrom, blueScore: 0, redScore: 0, winner: null });
  if (size === 4) {
    return [m(0, 1, sf, 0, 1, null, null), m(1, 1, sf, 2, 3, null, null), m(2, 2, fin, null, null, 0, 1)];
  }
  return [
    m(0, 1, qf, 0, 1, null, null),
    m(1, 1, qf, 2, 3, null, null),
    m(2, 1, qf, 4, 5, null, null),
    m(3, 1, qf, 6, 7, null, null),
    m(4, 2, sf, null, null, 0, 1),
    m(5, 2, sf, null, null, 2, 3),
    m(6, 3, fin, null, null, 4, 5),
  ];
}

